#!/usr/bin/env bash
# Stage the artifacts the spatial studio boots from.
#
# `guest-api.mjs` boots the `postcard-os` card from
# `workspace-prototype/data/master-images/postcard-minimal-kernel` (plus the
# optional `ramdisk.img`), not from `target/`. Copying the build output there
# keeps the default paths working without `POSTCARD_KERNEL`/`POSTCARD_RAMDISK`.
#
# Guest operating-system images are NOT bundled and cannot be generated by this
# script: the Debian golden base and the Windows disks are written by the
# studio's own install flow (see workspace-prototype/README.md).
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "${SCRIPT_DIR}/.." && pwd)"
DATA_DIR="${POSTCARD_VM_DATA:-${REPO_ROOT}/workspace-prototype/data}"
MASTER_DIR="${DATA_DIR}/master-images"

mkdir -p \
    "${MASTER_DIR}" \
    "${DATA_DIR}/overlays" \
    "${DATA_DIR}/paper-planes" \
    "${DATA_DIR}/windows/disks" \
    "${DATA_DIR}/windows/firmware" \
    "${DATA_DIR}/windows/tpm"

KERNEL_ELF="${REPO_ROOT}/target/x86_64-unknown-none/release/postcard-minimal-kernel"
if [[ -f "${KERNEL_ELF}" ]]; then
    install -m 0755 "${KERNEL_ELF}" "${MASTER_DIR}/postcard-minimal-kernel"
    echo "staged kernel  -> ${MASTER_DIR}/postcard-minimal-kernel"
else
    echo "kernel not built yet: run 'make kernel' (looked for ${KERNEL_ELF})" >&2
fi

RAMDISK_IMG="${REPO_ROOT}/ramdisk.img"
if [[ -f "${RAMDISK_IMG}" ]]; then
    install -m 0644 "${RAMDISK_IMG}" "${MASTER_DIR}/ramdisk.img"
    echo "staged ramdisk -> ${MASTER_DIR}/ramdisk.img"
else
    echo "ramdisk not built yet: run 'make userland' (looked for ${RAMDISK_IMG})" >&2
fi

if [[ ! -f "${MASTER_DIR}/debian-golden.qcow2" ]]; then
    echo "no Debian golden base yet: install Debian on a Linux card, shut it down," \
        "then choose 'Finish base installation' (or set POSTCARD_LINUX_BASE)."
fi

windows_disks=("${DATA_DIR}/windows/disks/"*.qcow2)
if [[ ! -e "${windows_disks[0]}" ]]; then
    echo "no Windows disk yet: install Windows from your own ISO on a Windows card" \
        "(set POSTCARD_WINDOWS_ISO, never bundled)."
fi

echo "guest data directory: ${DATA_DIR}"
